66|  const scenes = asRecord(readJson(join(dir, "scenes.json")));
67|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
68|  const list = Array.isArray(scenes.scenes) ? (scenes.scenes as { id: unknown; ch: unknown; start_n: unknown; end_n: unknown; title: unknown; summary: unknown; characters: unknown }[]) : undefined;
69|  return { recorded: asString(asRecord(analysis.provenance).input), current: list === undefined ? "" : classifyInputOf(list) };
70|}
71|
72|export function resplitKeys(dir: string): StepKeys {
73|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
74|  const list = Array.isArray(analysis.scenes) ? (analysis.scenes as { id: unknown; start_n: unknown; end_n: unknown }[]) : undefined;
75|  return { recorded: asString(asRecord(asRecord(analysis.provenance).resplit).input), current: list === undefined ? "" : resplitInputOf(list) };
