1|// One freshness rule per pipeline step: each step compares the
2|// fingerprint of its real input against the key its last run recorded.
3|// Reuse only when the keys match and --force is off.
4|import { createHash } from "node:crypto";
5|import { readFileSync } from "node:fs";
6|import { join } from "node:path";
7|
8|export function fingerprint(value: unknown): string {
9|  return createHash("sha256").update(JSON.stringify(value)).digest("hex").slice(0, 16);
10|}
11|
12|export interface StepKeys {
13|  recorded: string | undefined;
14|  current: string;
15|}
16|
17|export interface FreshnessDecision {
18|  reuse: boolean;
19|  reason: string;
20|}
21|
22|export function decide(force: boolean, recorded: string | undefined, current: string): FreshnessDecision {
23|  if (force) return { reuse: false, reason: "forced" };
24|  if (recorded === undefined) return { reuse: false, reason: "no previous output" };
25|  if (recorded === current) return { reuse: true, reason: "inputs unchanged" };
26|  return { reuse: false, reason: "inputs changed" };
27|}
28|
29|function readJson(path: string): unknown {
30|  try {
31|    return JSON.parse(readFileSync(path, "utf8"));
32|  } catch {
33|    return undefined;
34|  }
35|}
36|
37|function asRecord(value: unknown): Record<string, unknown> {
38|  return typeof value === "object" && value !== null ? (value as Record<string, unknown>) : {};
39|}
40|
41|function asString(value: unknown): string | undefined {
42|  return typeof value === "string" ? value : undefined;
43|}
44|
45|export function classifyInputOf(scenes: { id: unknown; ch: unknown; start_n: unknown; end_n: unknown; title: unknown; summary: unknown; characters: unknown }[]): string {
46|  return fingerprint(
47|    scenes.map((s) => ({ id: s.id, ch: s.ch, start_n: s.start_n, end_n: s.end_n, title: s.title, summary: s.summary, characters: s.characters })),
48|  );
49|}
50|
51|export function resplitInputOf(scenes: { id: unknown; start_n: unknown; end_n: unknown }[]): string {
52|  return fingerprint(scenes.map((s) => ({ id: s.id, start_n: s.start_n, end_n: s.end_n })));
53|}
54|
55|export function clusterInputOf(scenes: { id: unknown; final: unknown }[]): string {
56|  return fingerprint(scenes.map((s) => ({ id: s.id, final: s.final })));
57|}
58|
59|export function segmentKeys(dir: string): StepKeys {
60|  const book = asRecord(readJson(join(dir, "book.json")));
61|  const scenes = asRecord(readJson(join(dir, "scenes.json")));
62|  return { recorded: asString(scenes.textVersion), current: asString(book.textVersion) ?? "" };
63|}
64|
65|export function classifyKeys(dir: string): StepKeys {
66|  const scenes = asRecord(readJson(join(dir, "scenes.json")));
67|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
68|  const list = Array.isArray(scenes.scenes) ? (scenes.scenes as { id: unknown; ch: unknown; start_n: unknown; end_n: unknown; title: unknown; summary: unknown; characters: unknown }[]) : undefined;
69|  return { recorded: asString(asRecord(analysis.provenance).input), current: list === undefined ? "" : classifyInputOf(list) };
70|}
71|
72|export function resplitKeys(dir: string): StepKeys {
73|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
74|  const list = Array.isArray(analysis.scenes) ? (analysis.scenes as { id: unknown; start_n: unknown; end_n: unknown }[]) : undefined;
75|  return { recorded: asString(asRecord(asRecord(analysis.provenance).resplit).input), current: list === undefined ? "" : resplitInputOf(list) };
76|}
77|
78|export function clusterKeys(dir: string): StepKeys {
79|  const analysis = asRecord(readJson(join(dir, "analysis.json")));
80|  const clusters = asRecord(readJson(join(dir, "music-clusters.json")));
81|  const list = Array.isArray(analysis.scenes) ? (analysis.scenes as { id: unknown; final: unknown }[]) : undefined;
82|  return { recorded: asString(asRecord(clusters.provenance).input), current: list === undefined ? "" : clusterInputOf(list) };
83|}
84|
85|export type FreshStep = "segment" | "classify" | "resplit" | "cluster";
86|
87|const STEP_ORDER: FreshStep[] = ["segment", "classify", "resplit", "cluster"];
88|
89|const STEP_KEYS: Record<FreshStep, (dir: string) => StepKeys> = { segment: segmentKeys, classify: classifyKeys, resplit: resplitKeys, cluster: clusterKeys };
90|
91|export interface StepPlan {
92|  step: FreshStep;
93|  reuse: boolean;
94|  reason: string;
95|}
96|
97|// Plans the selected steps in pipeline order. Once a step would redo,
98|// every later step redoes too, since its input comes from that step.
99|export function planSteps(dir: string, steps: FreshStep[], force: boolean): StepPlan[] {
100|  const wanted = STEP_ORDER.filter((step) => steps.includes(step));
101|  const plans: StepPlan[] = [];
102|  let upstreamRedoes = false;
103|  for (const step of wanted) {
104|    if (upstreamRedoes) {
105|      plans.push({ step, reuse: false, reason: "upstream step redoes" });
106|      continue;
107|    }
108|    const keys = STEP_KEYS[step](dir);
109|    const decision = decide(force, keys.recorded, keys.current);
110|    if (!decision.reuse) upstreamRedoes = true;
111|    plans.push({ step, ...decision });
112|  }
113|  return plans;
114|}

