110|
111|export async function runResplit(ctx: StepCtx, deps: { jev: JevClient; meta: MetaClient }): Promise<AnalyzedScene[]> {
112|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
113|  const scenesFile = JSON.parse(readFileSync(join(ctx.dir, "scenes.json"), "utf8")) as {
114|    bookId: string;
115|    textVersion: string;
116|    scenes: Scene[];
117|    provenance: { meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number } };
118|  };
119|  const analysisFile = JSON.parse(readFileSync(join(ctx.dir, "analysis.json"), "utf8")) as {
120|    bookId: string;
121|    textVersion: string;
122|    scenes: AnalyzedScene[];
123|    provenance: {
124|      date: string;
125|      jev: { model: string; requests: number; input_tokens: number; output_tokens: number; cost_usd: number };
126|      meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number };
127|      total_cost_usd: number;
128|      resplit?: unknown;
129|    };
130|  };
131|  const keys = resplitKeys(ctx.dir);
132|  if (decide(ctx.force, keys.recorded, keys.current).reuse) {
133|    return analysisFile.scenes;
134|  }
135|  const usage = newUsage(deps.meta.model);
136|  const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
137|  const chapterTitle = new Map(book.chapters.map((c) => [c.ch, c.title]));
138|  const wordsOf = (scene: { start_n: number; end_n: number }): number => {
139|    let words = 0;
140|    for (let n = scene.start_n; n <= scene.end_n; n++) words += countWords(byN.get(n) ?? "");
141|    return words;
142|  };
143|  const candidates = analysisFile.scenes.filter((s) => isResplitCandidate(wordsOf(s), s.final));
144|  let windowsClassified = 0;
145|  const windowFailures: string[] = [];
146|  const museFailures: { from: string; reason: string }[] = [];
147|  const rejected: ResplitRejected[] = [];
148|  const mergedBack: ResplitMergedBack[] = [];
149|
150|  const splitScenes = await runPool(candidates, 4, async (scene) => {
151|    const paragraphs = book.paragraphs.filter((p) => p.n >= scene.start_n && p.n <= scene.end_n);
152|    const spans = buildWindows(paragraphs);
153|    const windows: ResplitWindow[] = [];
154|    for (const span of spans) {
155|      const text = paragraphs.filter((p) => p.n >= span.startN && p.n <= span.endN).map((p) => p.text).join("\n");
156|      let result;
157|      try {
158|        result = await deps.jev.classify({ book: book.title, chapter: chapterTitle.get(scene.ch) ?? "", sceneTitle: scene.title, scene: text });
159|      } catch {
160|        windowFailures.push(scene.id);
161|        return null;
162|      }
163|      usage.jevRequests += 1;
164|      usage.jevInputTokens += result.input_tokens;
165|      usage.jevOutputTokens += result.output_tokens;
166|      const { unknown: _dropped, ...rest } = result.vector;
167|      const vector = renormalize8(rest);
168|      if (vector === null) {
169|        windowFailures.push(scene.id);
170|        return null;
171|      }
172|      windows.push({ ...span, vector });
173|      windowsClassified += 1;
174|    }
175|    if (windows.length < 2) return null;
176|    const taken: { call: SplitCall; by: "rule" | "muse" }[] = [];
177|    const reasons = new Map<number, string>();
178|    let cuts: number[];
179|    try {
180|      cuts = await planSplits(
181|        windows,
182|        async (call) => {
183|          const boundaryN = windows[call.index]?.startN ?? 0;
184|          const before = paragraphs.filter((p) => p.n < boundaryN).slice(-2);
185|          const after = paragraphs.filter((p) => p.n >= boundaryN).slice(0, 2);
186|          const left = meanVector(windows.slice(0, call.index));
187|          const right = meanVector(windows.slice(call.index));
188|          const result = await deps.meta.completeJson({
189|            system: "You judge whether a scene needs two music tracks. Answer with JSON only.",
190|            user:
191|              `Scene "${scene.title}" may change mood at paragraph ${windows[call.index]?.startN}. ` +
192|              `Left mood ${call.left} ${JSON.stringify(left)}, right mood ${call.right} ${JSON.stringify(right)}. ` +
193|              `Split only when the dominant feeling changes strongly and stays changed, not for a mixed blend. ` +
194|              `Before: ${before.map((p) => `[${p.n}] ${p.text}`).join("\n")}\nAfter: ${after.map((p) => `[${p.n}] ${p.text}`).join("\n")}`,
195|            schemaName: "resplit_decision",
196|            schema: DECISION_SCHEMA,
197|          });
198|          trackMeta(usage, result);
199|          const data = result.data as { split?: unknown; reason?: unknown };
200|          const split = data.split === true;
201|          const reason = String(data.reason ?? "");
202|          if (split) reasons.set(call.index, reason);
203|          else rejected.push({ from: scene.id, at_n: boundaryN, margin: call.margin, window_left: call.left, window_right: call.right, reason });
