208|    } catch (err) {
209|      museFailures.push({ from: scene.id, reason: museFailureReason(err) });
210|      return null;
211|    }
212|    if (cuts.length === 0) return null;
213|    const bounds = [0, ...cuts, windows.length];
214|    const ranges = bounds.slice(1).map((end, i) => ({ startN: windows[bounds[i] ?? 0]?.startN ?? 0, endN: windows[end - 1]?.endN ?? 0 }));
215|    let parts: { start_n: number; end_n: number; title: string; summary: string; characters: unknown }[];
216|    try {
217|      const result = await deps.meta.completeJson({
218|        system: "You split a book scene into ordered parts. Answer with JSON only, English titles in the style of the existing scene titles.",
219|        user:
220|          `Scene "${scene.title}" (${scene.id}, summary: ${scene.summary}) splits into ${ranges.length} parts. ` +
221|          `Give each part start_n, end_n, title, summary, and characters.\n` +
222|          ranges.map((r, i) => `PART ${i + 1} [${r.startN}..${r.endN}]:\n${paragraphs.filter((p) => p.n >= r.startN && p.n <= r.endN).map((p) => `[${p.n}] ${p.text}`).join("\n")}`).join("\n"),
223|        schemaName: "resplit_titles",
224|        schema: TITLES_SCHEMA,
225|      });
226|      trackMeta(usage, result);
227|      parts = (result.data as { parts?: { start_n: number; end_n: number; title: string; summary: string; characters: unknown }[] }).parts ?? [];
228|      if (parts.length !== ranges.length || parts.some((p, i) => p.start_n !== ranges[i]?.startN || p.end_n !== ranges[i]?.endN)) {
229|        throw new Error("titles do not cover the split ranges");
230|      }
231|    } catch (err) {
232|      museFailures.push({ from: scene.id, reason: museFailureReason(err) });
233|      return null;
234|    }
235|    const bases = parts.map((part) => ({
236|      ch: scene.ch,
237|      start_n: part.start_n,
238|      end_n: part.end_n,
239|      title: part.title,
240|      summary: part.summary,
241|      characters: Array.isArray(part.characters) ? part.characters.map(String) : [],
242|    }));
243|    const analyzed = await runPool(bases, 4, async (base) => {
244|      const text = paragraphs.filter((p) => p.n >= base.start_n && p.n <= base.end_n).map((p) => p.text).join("\n");
245|      const emotion = await classifyScene({ id: "", ...base }, text, book.title, chapterTitle.get(scene.ch) ?? "", deps, usage.meta);
246|      if (emotion.jev) {
247|        usage.jevRequests += 1;
248|        usage.jevInputTokens += emotion.jev.input_tokens;
249|        usage.jevOutputTokens += emotion.jev.output_tokens;
250|      }
251|      return emotion;
252|    });
253|    // Merge adjacent parts whose re-classified top emotion agrees; a
254|    // null final never merges. One extra classify per merged group.
255|    const tops = analyzed.map((e) => (e.final ? topOf(e.final.vector).id : null));
256|    const groups: number[][] = [];
257|    for (let i = 0; i < bases.length; i++) {
258|      const last = groups[groups.length - 1];
259|      const prev = last ? tops[last[last.length - 1] ?? -1] : undefined;
260|      const top = tops[i];
261|      if (last && top !== null && top === prev) last.push(i);
262|      else groups.push([i]);
263|    }
264|    if (groups.length === 1 && bases.length > 1) {
265|      mergedBack.push({ from: scene.id, top: tops[0] ?? null });
266|      return null;
267|    }
268|    const finals: { base: (typeof bases)[number]; emotion: SceneEmotion }[] = [];
269|    for (const group of groups) {
270|      if (group.length === 1) {
271|        const i = group[0] ?? 0;
272|        finals.push({ base: bases[i]!, emotion: (analyzed[i] ?? { jev: null, muse_override: null, final: null, error: "missing part emotion" }) as SceneEmotion });
273|        continue;
274|      }
275|      const first = bases[group[0] ?? 0]!;
276|      const lastBase = bases[group[group.length - 1] ?? 0]!;
277|      const base = { ...first, start_n: first.start_n, end_n: lastBase.end_n };
278|      const text = paragraphs.filter((p) => p.n >= base.start_n && p.n <= base.end_n).map((p) => p.text).join("\n");
279|      const emotion = await classifyScene({ id: "", ...base }, text, book.title, chapterTitle.get(scene.ch) ?? "", deps, usage.meta);
280|      if (emotion.jev) {
281|        usage.jevRequests += 1;
282|        usage.jevInputTokens += emotion.jev.input_tokens;
283|        usage.jevOutputTokens += emotion.jev.output_tokens;
284|      }
285|      finals.push({ base, emotion });
286|      mergedBack.push({ from: scene.id, top: emotion.final ? topOf(emotion.final.vector).id : null });
287|    }
288|    const ids = splitIds(scene.id, finals.length);
289|    const byCut = new Map(taken.map((t) => [t.call.index, t]));
290|    const finalTops = finals.map((f) => (f.emotion.final ? topOf(f.emotion.final.vector).id : null));
291|    // One entry per surviving cut; the window tops picked the cut and
292|    // the final tops are what the stored parts re-classified to.
293|    const entries: ResplitEntry[] = [];
294|    let start = 0;
295|    for (let g = 0; g + 1 < groups.length; g++) {
296|      const end = start + (groups[g]?.length ?? 0);
297|      const cutIndex = bounds[end] ?? 0;
298|      const call = byCut.get(cutIndex);
299|      const reason = reasons.get(cutIndex);
300|      entries.push({
301|        from: scene.id,
302|        at_n: finals[g + 1]?.base.start_n ?? 0,
303|        margin: call?.call.margin ?? 0,
304|        window_left: call?.call.left ?? "calma",
305|        window_right: call?.call.right ?? "calma",
306|        final_left: finalTops[g] ?? null,
307|        final_right: finalTops[g + 1] ?? null,
308|        decided_by: call?.by ?? "rule",
309|        ...(reason ? { reason } : {}),
310|      });
311|      start = end;
312|    }
313|    return {
314|      scene,
315|      parts: finals.map((f, i) => ({
316|        scene: { id: ids[i] ?? "", ...f.base } satisfies Scene,
317|        emotion: f.emotion,
318|      })),
319|      entries,
320|    };
321|  });
322|
323|  const byId = new Map(splitScenes.filter((s) => s !== null).map((s) => [s.scene.id, s]));
324|  const scenes: AnalyzedScene[] = [];
325|  const entries: ResplitEntry[] = [];
326|  for (const old of analysisFile.scenes) {
327|    const split = byId.get(old.id);
328|    if (!split) {
329|      scenes.push(old);
