111|    overrideRate = analysis.override_rate;
112|    jev = analysis.provenance.jev;
113|    meta = analysis.provenance.meta;
114|    total = analysis.provenance.total_cost_usd;
115|  } catch {
116|    // Steps after ingest may not have run yet.
117|  }
118|  const dist = new Map<string, number>();
119|  let failures = 0;
120|  for (const scene of scenes) {
121|    if (!scene.final) {
122|      failures += 1;
123|      continue;
124|    }
125|    const top = Object.entries(scene.final.vector).sort((a, b) => b[1] - a[1])[0]?.[0] ?? "?";
126|    dist.set(top, (dist.get(top) ?? 0) + 1);
127|  }
128|  console.log(`summary: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${scenes.length} scenes`);
129|  console.log(`emotions: ${[...dist.entries()].map(([id, count]) => `${id} ${count}`).join(", ") || "none yet"}`);
130|  console.log(`override rate ${((overrideRate ?? 0) * 100).toFixed(1)}%, failures ${failures}`);
131|  console.log(`cost: jev $${(jev.cost_usd ?? 0).toFixed(4)}, meta $${(meta.cost_usd ?? 0).toFixed(4)}, total $${(total ?? 0).toFixed(4)}`);
132|}
133|
134|main().catch((error: unknown) => {
135|  console.error(`error: ${(error as Error).message}`);
136|  process.exit(1);
137|});

